MIGRATION_PATH = 'supabase/migrations/0013_prediction_double.sql'
MIGRATION_B64 = ''


def fail(msg: str) -> None:
    print(f"\n\033[31m✗ {msg}\033[0m", file=sys.stderr)
    sys.exit(1)


def apply_patches() -> None:
    for rel_path, target_b64, hunks in PATCHES:
        path = REPO_ROOT / rel_path
        if not path.exists():
            fail(f"File not found: {rel_path}")

        text = path.read_text(encoding="utf-8")
        target = base64.b64decode(target_b64).decode("utf-8")

        if text == target:
            print(f"= {rel_path} (already applied, skipping)")
            continue

        for idx, (old_b64, new_b64) in enumerate(hunks, start=1):
            old_snip = base64.b64decode(old_b64).decode("utf-8")
            new_snip = base64.b64decode(new_b64).decode("utf-8")

            count = text.count(old_snip)
            if count == 0:
                fail(
                    f"{rel_path}: hunk {idx}/{len(hunks)} search text not found.\n"
                    "The file changed since this script was generated "
                    "(or was already partially patched by hand). "
                    "Refusing to apply blindly."
                )
            if count > 1:
                fail(
                    f"{rel_path}: hunk {idx}/{len(hunks)} search text matches "
                    f"{count} locations (expected exactly 1). Refusing to guess."
                )
            text = text.replace(old_snip, new_snip, 1)

        if text != target:
            fail(
                f"{rel_path}: all hunks applied but result does not match the "
                "expected target content. Refusing to write a mismatched file."
            )

        path.write_text(text, encoding="utf-8")
        print(f"✓ patched {rel_path} ({len(hunks)} hunk(s))")


def create_migration() -> None:
    path = REPO_ROOT / MIGRATION_PATH
    content = base64.b64decode(MIGRATION_B64)
    if path.exists():
        if path.read_bytes() == content:
            print(f"= {MIGRATION_PATH} (already exists, identical, skipping)")
            return
        fail(
            f"{MIGRATION_PATH} already exists with different content — "
            "refusing to overwrite a migration file. Remove it first if you "
            "intend to regenerate it."
        )
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(content)
    print(f"✓ created {MIGRATION_PATH}")


def main() -> None:
    print("Applying prediction-double feature patch...\n")
    apply_patches()
    create_migration()
    print(
        "\nDone. Remaining work NOT covered by this script (by design — see "
        "chat):\n"
        "  1. Existing test files that instantiate SubmitPrediction directly\n"
        "     (submit_prediction_test.dart, round_predictions_test.dart) need a\n"
        "     fixtureScheduleRepository fake + isDouble on their score fixtures,\n"
        "     or they will fail to compile / fail on 'double_not_selected'.\n"
        "  2. Domain/contracts/infrastructure test suites for the touched files\n"
        "     (prediction_test.dart, fixture_score_prediction_test.dart,\n"
        "     scoring_test.dart, scoring_ruleset_test.dart, prediction_dto_test.dart,\n"
        "     postgres_prediction_repository_test.dart) need new cases for:\n"
        "     multiple_doubles, double_not_selected, fixture_locked,\n"
        "     no_open_fixtures, the missed grade, and the double multiplier.\n"
        "  3. The mobile prediction screen (deliberately out of scope for this\n"
        "     pass, per the agreed sequencing).\n"
        "Run `flutter test` after step 1-2 to confirm; expect red until then.\n"
    )


if __name__ == '__main__':
    main()
